contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(recipient != address(0), "invalid recipient");
        require(recipient != address(c), "recipient must not be the contract");

        uint256 preBalance = address(c).balance;
        uint256 preRecipient = recipient.balance;

        bool reverted;
        c.withdrawAll(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 postBalance = address(c).balance;
        uint256 postRecipient = recipient.balance;

        assert(reverted ? postBalance == preBalance : (postBalance == 0 && postRecipient == preRecipient + preBalance));
    }

    receive() external payable {}
}

